for r in select * from jsonb_to_recordset($json$[{"key": "t16-murmansk", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nНезамерзающий порт за полярным кругом\nМурманск расположен на берегу Кольского залива Баренцева моря, примерно в 200 км к северу от Северного полярного круга. Это крупнейший в мире город за полярным кругом. Зимой здесь наступает полярная ночь, которая длится около 40 суток, а средняя температура января около –10 °С. Однако Кольский залив зимой не замерзает, и порт работает круглый год. Отсюда начинается Северный морской путь, сюда приходят суда с грузами, базируется рыболовный флот. А вот порты Белого моря, лежащие южнее, зимой скованы льдом и без ледоколов не работают.\n\nКак называются постоянные потоки воды в Мировом океане, переносящие огромные массы воды на большие расстояния?", "answer": "течения", "accepted": ["течения", "течение", "океанические течения", "морские течения", "океанические течения (морские течения)"], "short": "Постоянные перемещения больших масс воды в океане в определённом направлении называются океаническими (морскими) течениями.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «волны» или «приливы»: волны не переносят воду на большие расстояния, а приливы меняют направление дважды в сутки.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-murmansk", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nНезамерзающий порт за полярным кругом\nМурманск расположен на берегу Кольского залива Баренцева моря, примерно в 200 км к северу от Северного полярного круга. Это крупнейший в мире город за полярным кругом. Зимой здесь наступает полярная ночь, которая длится около 40 суток, а средняя температура января около –10 °С. Однако Кольский залив зимой не замерзает, и порт работает круглый год. Отсюда начинается Северный морской путь, сюда приходят суда с грузами, базируется рыболовный флот. А вот порты Белого моря, лежащие южнее, зимой скованы льдом и без ледоколов не работают.\n\nОбъясните, почему Кольский залив, в котором расположен Мурманск, зимой не замерзает, хотя порты Белого моря, лежащие южнее, покрываются льдом.", "answer": "В Баренцево море приходит тёплое течение (продолжение Северо-Атлантического течения, Гольфстрима). Оно приносит тёплую воду, поэтому Кольский залив не замерзает, а в закрытое Белое море тёплые воды не проникают.", "accepted": null, "short": "К берегам Кольского полуострова доходит тёплое течение — продолжение Гольфстрима. Тёплая вода не даёт заливу замёрзнуть.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Ссылаются на солёность воды или на ветры. Главная причина — тёплое течение.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о влиянии тёплого течения (Северо-Атлантического, Нордкапского, Гольфстрима), которое приносит тёплую воду к Кольскому полуострову.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-iceland", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nСтрана льда и огня\nИсландия — остров на севере Атлантического океана. Его называют страной льда и огня: ледники покрывают около 11 % территории, а под ними и рядом с ними находятся действующие вулканы. Извержения происходят в среднем раз в несколько лет. В 2010 году извержение вулкана Эйяфьятлайёкюдль выбросило в атмосферу столько пепла, что над Европой почти на неделю закрыли воздушное движение. Через весь остров с юго-запада на северо-восток тянется полоса трещин в земной коре, которая каждый год расширяется примерно на 2 см. Горячие подземные воды исландцы используют для отопления домов и теплиц.\n\nКак называются горные поднятия на дне океанов, протягивающиеся на десятки тысяч километров, вдоль которых раздвигаются литосферные плиты?", "answer": "срединно-океанические хребты", "accepted": ["срединно-океанические хребты", "срединно-океанический хребет", "срединно океанический хребет", "срединно-океанические хребты (СОХ)", "срединные хребты", "срединный хребет", "подводные хребты"], "short": "Вдоль границ расходящихся океанических плит на дне образуются срединно-океанические хребты. Исландия — выход такого хребта на поверхность.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «горы» или «желоба»: глубоководные желоба образуются там, где плиты сходятся, а не раздвигаются.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-iceland", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nСтрана льда и огня\nИсландия — остров на севере Атлантического океана. Его называют страной льда и огня: ледники покрывают около 11 % территории, а под ними и рядом с ними находятся действующие вулканы. Извержения происходят в среднем раз в несколько лет. В 2010 году извержение вулкана Эйяфьятлайёкюдль выбросило в атмосферу столько пепла, что над Европой почти на неделю закрыли воздушное движение. Через весь остров с юго-запада на северо-восток тянется полоса трещин в земной коре, которая каждый год расширяется примерно на 2 см. Горячие подземные воды исландцы используют для отопления домов и теплиц.\n\nОбъясните, почему в Исландии много действующих вулканов.", "answer": "Исландия расположена на срединно-океаническом хребте — на границе литосферных плит, которые раздвигаются (Северо-Американской и Евразийской). По трещинам между ними поднимается магма, поэтому здесь много вулканов.", "accepted": null, "short": "Исландия лежит прямо на границе двух расходящихся плит. В трещину между ними поднимается магма — отсюда вулканы.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что там холодно» или «из-за ледников». Ледники не связаны с вулканами — причина в границе плит.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о расположении Исландии на границе литосферных плит (на срединно-океаническом хребте, в месте раздвижения плит).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-tanganyika", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nОзёра Восточной Африки\nВ Восточной Африке цепочкой протянулись крупные озёра: Ньяса, Танганьика, Альберт, Эдуард, Киву и другие. Почти все они узкие и вытянутые, с крутыми берегами. Танганьика имеет длину около 670 км, а ширину всего около 50 км; её глубина достигает 1470 м — это второе по глубине озеро мира. Котловины озёр лежат на дне огромных трещин в земной коре, которые протягиваются на тысячи километров от Красного моря до долины реки Замбези. Рядом с озёрами возвышаются вулканы, в том числе Килиманджаро. В этих местах нередко происходят землетрясения.\n\nКак называются глубокие трещины в земной коре, вдоль которых происходят смещения её участков?", "answer": "разломы", "accepted": ["разломы", "разлом", "разломы земной коры", "тектонические разломы", "рифты", "рифт", "рифтовые долины", "грабены", "трещины земной коры"], "short": "Трещины в земной коре, по которым её участки смещаются, называются разломами. Крупные разломы в Восточной Африке образуют рифтовые долины.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «овраги» или «каньоны» — они образуются при размыве текущей водой, а не при движениях земной коры.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-tanganyika", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nОзёра Восточной Африки\nВ Восточной Африке цепочкой протянулись крупные озёра: Ньяса, Танганьика, Альберт, Эдуард, Киву и другие. Почти все они узкие и вытянутые, с крутыми берегами. Танганьика имеет длину около 670 км, а ширину всего около 50 км; её глубина достигает 1470 м — это второе по глубине озеро мира. Котловины озёр лежат на дне огромных трещин в земной коре, которые протягиваются на тысячи километров от Красного моря до долины реки Замбези. Рядом с озёрами возвышаются вулканы, в том числе Килиманджаро. В этих местах нередко происходят землетрясения.\n\nОбъясните, почему озёра Восточной Африки (Ньяса, Танганьика и др.) узкие, вытянутые и очень глубокие.", "answer": "Их котловины образовались в разломах земной коры: здесь литосферная плита раскалывается и её части раздвигаются. Озёра заполнили вытянутые глубокие впадины в разломах, поэтому они узкие, длинные и глубокие.", "accepted": null, "short": "Котловины этих озёр — это разломы земной коры, где плита раскалывается. Вода заполнила глубокие вытянутые трещины.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «озёра вырыл ледник» или «их наполнили реки». Ледников здесь не было, форма котловины — от разломов.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о тектоническом происхождении котловин озёр (котловины образовались в разломах земной коры / в местах раздвижения литосферных плит).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-himalaya", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nЗемлетрясение в Непале\nВ апреле 2015 года в Непале произошло сильнейшее за 80 лет землетрясение. Подземные толчки ощущались в Индии, Китае и Бангладеш. В столице страны Катманду рухнули многие старинные храмы, а на склонах Эвереста землетрясение вызвало сход лавин. Учёные установили, что после землетрясения некоторые участки земной поверхности поднялись почти на метр. Гималаи — самые высокие горы на Земле; измерения показывают, что они продолжают расти примерно на несколько миллиметров в год. Землетрясения в этом районе случаются часто.\n\nКак называется место в недрах Земли, где возникает землетрясение (происходит разрыв и смещение горных пород)?", "answer": "очаг землетрясения", "accepted": ["очаг землетрясения", "очаг", "гипоцентр", "очаг (гипоцентр)", "гипоцентр землетрясения"], "short": "Место в глубине Земли, где происходит разрыв горных пород, — очаг (гипоцентр). Точка на поверхности над ним — эпицентр.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «эпицентр»: эпицентр — это место на поверхности над очагом, а не в недрах.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-himalaya", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nЗемлетрясение в Непале\nВ апреле 2015 года в Непале произошло сильнейшее за 80 лет землетрясение. Подземные толчки ощущались в Индии, Китае и Бангладеш. В столице страны Катманду рухнули многие старинные храмы, а на склонах Эвереста землетрясение вызвало сход лавин. Учёные установили, что после землетрясения некоторые участки земной поверхности поднялись почти на метр. Гималаи — самые высокие горы на Земле; измерения показывают, что они продолжают расти примерно на несколько миллиметров в год. Землетрясения в этом районе случаются часто.\n\nОбъясните, почему Гималаи продолжают расти, а в Непале часто происходят землетрясения.", "answer": "Гималаи находятся на границе литосферных плит: Индо-Австралийская плита надвигается на Евразийскую. При столкновении плит земная кора сминается и поднимается, поэтому горы растут, а движения плит вызывают землетрясения.", "accepted": null, "short": "Индийская плита продолжает надвигаться на Евразийскую. Кора на границе сминается — горы растут, а резкие подвижки плит дают землетрясения.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «из-за вулканов»: в Гималаях вулканов нет. Причина — столкновение плит.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о расположении на границе сходящихся (сталкивающихся) литосферных плит — Индо-Австралийской (Индийской) и Евразийской.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-sahara-dust", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nПыль Сахары над океаном\nКаждый год ветры поднимают над Сахарой сотни миллионов тонн пыли. Спутниковые снимки показывают, как огромные пылевые облака протягиваются над Атлантическим океаном на тысячи километров к западу и достигают Карибских островов и Южной Америки. Учёные подсчитали, что пыль из Сахары приносит в леса бассейна Амазонки фосфор и другие вещества, которые удобряют бедные почвы экваториальных лесов. Пыль переносят ветры, которые круглый год дуют в тропических широтах в сторону экватора.\n\nКак называются постоянные ветры, дующие круглый год от тропических широт к экватору?", "answer": "пассаты", "accepted": ["пассаты", "пассат", "северо-восточные пассаты", "северо-восточный пассат"], "short": "Постоянные ветры, дующие от поясов высокого давления у тропиков к экватору, называются пассатами.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «муссоны» (они меняют направление по сезонам) или «западные ветры» (они дуют в умеренных широтах).", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-sahara-dust", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nПыль Сахары над океаном\nКаждый год ветры поднимают над Сахарой сотни миллионов тонн пыли. Спутниковые снимки показывают, как огромные пылевые облака протягиваются над Атлантическим океаном на тысячи километров к западу и достигают Карибских островов и Южной Америки. Учёные подсчитали, что пыль из Сахары приносит в леса бассейна Амазонки фосфор и другие вещества, которые удобряют бедные почвы экваториальных лесов. Пыль переносят ветры, которые круглый год дуют в тропических широтах в сторону экватора.\n\nОбъясните, почему пыль из Сахары переносится через Атлантический океан именно на запад, к Южной Америке.", "answer": "В тропических широтах Северного полушария дуют северо-восточные пассаты: из-за вращения Земли они отклоняются и дуют с востока на запад. Они и переносят пыль от Африки на запад, через океан к Южной Америке.", "accepted": null, "short": "Пассаты Северного полушария дуют с северо-востока на юго-запад, то есть от Африки к Америке — они и несут пыль.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут просто «ветер дует туда». Нужно назвать постоянный ветер — пассат — и его направление с востока на запад.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о переносе пыли пассатами, дующими с востока на запад (северо-восточными пассатами).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-roaring40", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\n«Ревущие сороковые»\nМоряки называют широты между 40° и 50° ю. ш. «ревущими сороковыми». Здесь почти круглый год дуют сильные устойчивые ветры с запада на восток, часто бывают штормы, а высота волн нередко превышает 10 м. В эпоху парусного флота корабли специально спускались в эти широты, чтобы с попутным ветром быстрее добраться из Европы до Австралии. Ещё южнее, за 50° ю. ш., лежат «неистовые пятидесятые», где ветры ещё сильнее. В Северном полушарии на этих же широтах ветры тоже дуют с запада, но они заметно слабее и неустойчивее.\n\nКак называются ветры, преобладающие в умеренных широтах обоих полушарий и дующие с запада на восток?", "answer": "западные ветры", "accepted": ["западные ветры", "западные ветра", "западный перенос", "западный ветер", "ветры западного переноса"], "short": "В умеренных широтах преобладает западный перенос воздуха — западные ветры.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «пассаты»: пассаты дуют в тропиках к экватору, а не в умеренных широтах.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-roaring40", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\n«Ревущие сороковые»\nМоряки называют широты между 40° и 50° ю. ш. «ревущими сороковыми». Здесь почти круглый год дуют сильные устойчивые ветры с запада на восток, часто бывают штормы, а высота волн нередко превышает 10 м. В эпоху парусного флота корабли специально спускались в эти широты, чтобы с попутным ветром быстрее добраться из Европы до Австралии. Ещё южнее, за 50° ю. ш., лежат «неистовые пятидесятые», где ветры ещё сильнее. В Северном полушарии на этих же широтах ветры тоже дуют с запада, но они заметно слабее и неустойчивее.\n\nОбъясните, почему в умеренных широтах Южного полушария западные ветры намного сильнее и устойчивее, чем в Северном полушарии.", "answer": "В умеренных широтах Южного полушария почти нет суши — там сплошной океан. Ветры не встречают на пути материков и гор, которые их тормозят, поэтому они сильные и устойчивые.", "accepted": null, "short": "Над сплошным океаном ветрам нечему мешать: нет материков и гор, поэтому западные ветры разгоняются и не ослабевают.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «там холоднее» — дело не в температуре, а в том, что над океаном нет препятствий для ветра.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о том, что в умеренных широтах Южного полушария преобладает водная поверхность (почти нет суши), и ветрам не мешают материки и горы.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-oymyakon", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nПолюс холода\nСело Оймякон в Якутии называют полюсом холода Северного полушария: здесь отмечали морозы до –67,7 °С. Средняя температура января около –46 °С, а летом бывает жарко, до +30 °С. Оймякон расположен в глубокой котловине, окружённой горными хребтами, в тысячах километров от тёплых морей. Зимой над Восточной Сибирью устанавливается область высокого давления: погода стоит ясная и безветренная, а тяжёлый холодный воздух стекает со склонов и застаивается в котловинах. Снега выпадает немного, осадков за год всего около 200 мм.\n\nКак называется область высокого атмосферного давления, в которой устанавливается ясная безветренная погода?", "answer": "антициклон", "accepted": ["антициклон", "антициклоны", "область высокого давления — антициклон", "сибирский антициклон", "азиатский антициклон"], "short": "Область высокого давления с нисходящими движениями воздуха и ясной погодой называется антициклоном.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «циклон»: циклон — область низкого давления с облачной погодой и осадками.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-oymyakon", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nПолюс холода\nСело Оймякон в Якутии называют полюсом холода Северного полушария: здесь отмечали морозы до –67,7 °С. Средняя температура января около –46 °С, а летом бывает жарко, до +30 °С. Оймякон расположен в глубокой котловине, окружённой горными хребтами, в тысячах километров от тёплых морей. Зимой над Восточной Сибирью устанавливается область высокого давления: погода стоит ясная и безветренная, а тяжёлый холодный воздух стекает со склонов и застаивается в котловинах. Снега выпадает немного, осадков за год всего около 200 мм.\n\nОбъясните, почему в Оймяконе такие сильные зимние морозы и такая большая разница между зимними и летними температурами.", "answer": "Оймякон расположен в глубине материка, далеко от океанов (резко континентальный климат): тёплые морские воздушные массы сюда не доходят, а зимой суша сильно выхолаживается. Кроме того, село лежит в котловине, где застаивается холодный воздух.", "accepted": null, "short": "Далеко от океана суша зимой сильно остывает, а летом быстро прогревается — климат резко континентальный. Котловина ещё и собирает холодный воздух.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что далеко на севере». Широта важна, но на той же широте в Норвегии гораздо теплее — главное удалённость от океана.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится об удалённости от океанов (резко континентальном климате) ИЛИ о расположении в котловине, где застаивается холодный воздух.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-deadsea", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nМёртвое море\nМёртвое море — озеро на границе Израиля и Иордании. Его поверхность лежит примерно на 430 м ниже уровня океана — это самое низкое место на суше. Содержание солей в воде около 340 ‰, почти в 10 раз выше, чем в океане, поэтому человек лежит на воде, не погружаясь. В водах моря нет рыб, живут лишь некоторые микроорганизмы. Озеро питает река Иордан, а вытекающих рек нет. Климат здесь жаркий и очень сухой: летом температура превышает +40 °С, а осадков выпадает меньше 100 мм в год. В последние десятилетия воду Иордана разбирают на орошение, и уровень Мёртвого моря быстро понижается.\n\nКак называется количество солей, растворённых в 1 литре (1 кг) воды, выраженное в промилле (‰)?", "answer": "солёность", "accepted": ["солёность", "соленость", "солёность воды", "соленость воды", "минерализация"], "short": "Количество граммов солей в 1 кг (литре) воды называется солёностью и измеряется в промилле (‰).", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «плотность» или «минеральность». Принятый термин — солёность.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-deadsea", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nМёртвое море\nМёртвое море — озеро на границе Израиля и Иордании. Его поверхность лежит примерно на 430 м ниже уровня океана — это самое низкое место на суше. Содержание солей в воде около 340 ‰, почти в 10 раз выше, чем в океане, поэтому человек лежит на воде, не погружаясь. В водах моря нет рыб, живут лишь некоторые микроорганизмы. Озеро питает река Иордан, а вытекающих рек нет. Климат здесь жаркий и очень сухой: летом температура превышает +40 °С, а осадков выпадает меньше 100 мм в год. В последние десятилетия воду Иордана разбирают на орошение, и уровень Мёртвого моря быстро понижается.\n\nОбъясните, почему солёность воды в Мёртвом море очень высокая.", "answer": "Из Мёртвого моря не вытекает ни одна река (оно бессточное), а в жарком сухом климате вода сильно испаряется. Соли, которые приносит Иордан, остаются в озере и накапливаются.", "accepted": null, "short": "Вода уходит из озера только испарением, а соли остаются. В жару испарение огромное, поэтому соль накапливается.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что это море». На самом деле это бессточное озеро; соль накапливается из-за испарения.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о сильном испарении в жарком сухом климате ИЛИ о том, что озеро бессточное (из него не вытекают реки), и соли накапливаются.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-caspian", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nКаспийское море\nКаспийское море — самое большое озеро на Земле: его площадь около 370 тыс. км². Морем его называют из-за больших размеров, солёной воды и сильных штормов. Каспий лежит во внутренних районах Евразии, его поверхность находится почти на 28 м ниже уровня океана. Около 80 % речной воды в озеро приносит Волга, а вытекающих рек нет; вода уходит только на испарение. Уровень Каспия за последние сто лет то понижался, то повышался на несколько метров, а в последние годы снова быстро падает, и мелеют северные заливы.\n\nКак называется озеро, из которого не вытекает ни одна река?", "answer": "бессточное", "accepted": ["бессточное", "бессточное озеро", "бессточные озёра", "бессточные озера", "бессточный водоём"], "short": "Озеро, из которого не вытекают реки, называется бессточным; вода из него уходит только на испарение.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «солёное» или «внутреннее». Солёным бывает и сточное озеро; термин — бессточное.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-caspian", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nКаспийское море\nКаспийское море — самое большое озеро на Земле: его площадь около 370 тыс. км². Морем его называют из-за больших размеров, солёной воды и сильных штормов. Каспий лежит во внутренних районах Евразии, его поверхность находится почти на 28 м ниже уровня океана. Около 80 % речной воды в озеро приносит Волга, а вытекающих рек нет; вода уходит только на испарение. Уровень Каспия за последние сто лет то понижался, то повышался на несколько метров, а в последние годы снова быстро падает, и мелеют северные заливы.\n\nОбъясните, почему уровень воды в Каспийском море меняется.", "answer": "Уровень Каспия зависит от соотношения притока речной воды (прежде всего Волги) и испарения. В многоводные годы, когда в бассейне Волги выпадает много осадков, уровень растёт; в маловодные и жаркие годы испарение больше притока, и уровень падает.", "accepted": null, "short": "Каспий бессточный: вода приходит с реками и уходит испарением. Когда Волга приносит меньше воды или жарко — уровень падает.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «из-за приливов» — на Каспии нет заметных приливов. Причина — баланс притока и испарения.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о зависимости уровня от количества воды, приносимой реками (прежде всего Волгой), и/или от испарения (соотношения притока и испарения).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-nile", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nРазливы Нила\nНил — одна из самых длинных рек мира. В Египте, где дождей почти не бывает, река течёт через пустыню. Тем не менее каждый год в конце лета Нил поднимался на несколько метров и затоплял долину, а после спада воды на полях оставался плодородный ил. Древние египтяне вели по этим разливам календарь. Бóльшую часть летней воды в Нил приносит его приток Голубой Нил, который начинается на Эфиопском нагорье. После строительства Асуанской плотины в 1970 году разливы в Египте прекратились: воду задерживает огромное водохранилище.\n\nКак называется сильный и быстрый подъём уровня воды в реке, вызванный ливнями или быстрым таянием снега?", "answer": "паводок", "accepted": ["паводок", "паводки", "половодье", "разлив", "наводнение", "паводок (половодье)"], "short": "Быстрый подъём воды в реке после ливней — паводок; ежегодный сезонный подъём, например от таяния снега, — половодье.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «прилив»: приливы бывают в морях и вызваны Луной, а не дождями.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-nile", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nРазливы Нила\nНил — одна из самых длинных рек мира. В Египте, где дождей почти не бывает, река течёт через пустыню. Тем не менее каждый год в конце лета Нил поднимался на несколько метров и затоплял долину, а после спада воды на полях оставался плодородный ил. Древние египтяне вели по этим разливам календарь. Бóльшую часть летней воды в Нил приносит его приток Голубой Нил, который начинается на Эфиопском нагорье. После строительства Асуанской плотины в 1970 году разливы в Египте прекратились: воду задерживает огромное водохранилище.\n\nОбъясните, почему Нил разливался летом, хотя в Египте в это время дождей почти не бывает.", "answer": "Летом на Эфиопском нагорье, где берёт начало Голубой Нил, наступает сезон дождей (субэкваториальный климат, летние ливни). Вода с нагорья по притокам поступает в Нил и вызывает его подъём далеко вниз по течению, в Египте.", "accepted": null, "short": "Причина разлива — не в Египте, а в верховьях: летом на Эфиопском нагорье идут ливни, и Голубой Нил несёт эту воду в Египет.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «таяли ледники» — на Эфиопском нагорье ледников нет; причина в летних дождях.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о летних дождях в верховьях Нила / на Эфиопском нагорье (влажный сезон в субэкваториальном поясе), откуда вода поступает в Нил.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-australia-artesian", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nВода под пустыней\nАвстралия — самый сухой населённый материк. Почти в половине его территории нет постоянных рек, а многие реки наполняются водой только после редких дождей; такие пересыхающие русла австралийцы называют «крики». Внутренние районы занимают пустыни и полупустыни. Зато под большой частью материка лежит один из крупнейших в мире бассейнов подземных вод. Вода, просочившаяся в землю у подножия гор на востоке, медленно движется между водоупорными пластами и поднимается в скважинах сама, под давлением. Эту воду используют для водопоя овец и крупного рогатого скота.\n\nКак называются подземные воды, залегающие между водоупорными слоями и поднимающиеся в скважинах под давлением?", "answer": "артезианские", "accepted": ["артезианские", "артезианские воды", "артезианская вода", "межпластовые напорные воды", "напорные воды"], "short": "Межпластовые воды, которые находятся под давлением и сами поднимаются в скважинах, называются артезианскими.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «грунтовые воды»: грунтовые воды лежат над первым водоупорным слоем и не поднимаются под давлением.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-australia-artesian", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nВода под пустыней\nАвстралия — самый сухой населённый материк. Почти в половине его территории нет постоянных рек, а многие реки наполняются водой только после редких дождей; такие пересыхающие русла австралийцы называют «крики». Внутренние районы занимают пустыни и полупустыни. Зато под большой частью материка лежит один из крупнейших в мире бассейнов подземных вод. Вода, просочившаяся в землю у подножия гор на востоке, медленно движется между водоупорными пластами и поднимается в скважинах сама, под давлением. Эту воду используют для водопоя овец и крупного рогатого скота.\n\nОбъясните, почему во внутренних районах Австралии мало рек и преобладают пустыни.", "answer": "Бóльшая часть Австралии лежит в тропическом поясе, где господствует высокое давление и сухой тропический воздух. Влажные пассаты с Тихого океана задерживает Большой Водораздельный хребет на востоке, и во внутренние районы влага почти не доходит.", "accepted": null, "short": "Тропики — зона высокого давления, дождей мало. А влагу с Тихого океана перехватывают горы на востоке материка.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что жарко». Жара сама по себе не объясняет: нужно сказать про тропический пояс высокого давления или про горы на востоке.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о расположении в тропическом поясе (высокое давление, сухой тропический воздух) ИЛИ о том, что влажные ветры с океана задерживают горы на востоке (Большой Водораздельный хребет).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-reef", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nБольшой Барьерный риф\nБольшой Барьерный риф протянулся вдоль северо-восточного побережья Австралии более чем на 2000 км. Это самое крупное в мире сооружение, созданное живыми организмами, — его видно даже из космоса. Риф состоит из тысяч отдельных рифов и сотен островов, сложенных скелетами крошечных коралловых полипов. Кораллы живут только в чистой тёплой воде с температурой не ниже +20 °С. Вдоль восточного побережья Австралии на юг течёт тёплое течение, а у западного побережья материка проходит холодное течение, и крупных рифов там нет.\n\nКак называются кольцевые коралловые острова с мелководной лагуной в центре, характерные для тропических частей Тихого и Индийского океанов?", "answer": "атоллы", "accepted": ["атоллы", "атолл", "коралловые атоллы", "кольцевые коралловые острова"], "short": "Кольцевые коралловые острова с лагуной посередине называются атоллами.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «рифы» — риф может быть любой формы; кольцевой коралловый остров с лагуной — атолл.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-reef", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nБольшой Барьерный риф\nБольшой Барьерный риф протянулся вдоль северо-восточного побережья Австралии более чем на 2000 км. Это самое крупное в мире сооружение, созданное живыми организмами, — его видно даже из космоса. Риф состоит из тысяч отдельных рифов и сотен островов, сложенных скелетами крошечных коралловых полипов. Кораллы живут только в чистой тёплой воде с температурой не ниже +20 °С. Вдоль восточного побережья Австралии на юг течёт тёплое течение, а у западного побережья материка проходит холодное течение, и крупных рифов там нет.\n\nОбъясните, почему крупный коралловый риф образовался у восточного, а не у западного побережья Австралии.", "answer": "Вдоль восточного побережья Австралии проходит тёплое Восточно-Австралийское течение, поэтому вода там тёплая, как нужно кораллам. У западного побережья проходит холодное Западно-Австралийское течение, вода холоднее, и кораллы хуже растут.", "accepted": null, "short": "Кораллам нужна тёплая вода. У восточного берега её приносит тёплое течение, у западного проходит холодное.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «там больше солнца» — Солнце светит одинаково, разница в температуре воды из-за течений.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о тёплом течении у восточного побережья ИЛИ о холодном течении у западного побережья Австралии.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-typhoon", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nСтихия на Филиппинах\nФилиппины расположены на островах в западной части Тихого океана. Каждый год с июля по ноябрь сюда приходит в среднем около 20 тропических циклонов. Скорость ветра в них может превышать 250 км/ч, а ливни за сутки дают больше осадков, чем в Москве выпадает за год. В ноябре 2013 года циклон «Хайян» разрушил целые города, без крова остались миллионы человек. Такие циклоны зарождаются над океаном, где температура поверхностной воды превышает +26 °С, а над сушей быстро ослабевают.\n\nКак называются тропические циклоны, возникающие в северо-западной части Тихого океана?", "answer": "тайфуны", "accepted": ["тайфуны", "тайфун", "тропические циклоны", "тропический циклон"], "short": "Тропические циклоны в северо-западной части Тихого океана называют тайфунами, в Атлантике — ураганами.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «торнадо» или «смерч»: смерч — узкий вихрь диаметром в сотни метров, а тайфун — огромный циклон в сотни километров.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-typhoon", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nСтихия на Филиппинах\nФилиппины расположены на островах в западной части Тихого океана. Каждый год с июля по ноябрь сюда приходит в среднем около 20 тропических циклонов. Скорость ветра в них может превышать 250 км/ч, а ливни за сутки дают больше осадков, чем в Москве выпадает за год. В ноябре 2013 года циклон «Хайян» разрушил целые города, без крова остались миллионы человек. Такие циклоны зарождаются над океаном, где температура поверхностной воды превышает +26 °С, а над сушей быстро ослабевают.\n\nОбъясните, почему тропические циклоны зарождаются над тёплыми водами океана, а над сушей быстро ослабевают.", "answer": "Над тёплой водой сильно испаряется влага, тёплый влажный воздух поднимается вверх, водяной пар конденсируется и выделяет тепло, которое питает энергией циклон. Над сушей притока тепла и влаги от океана нет, поэтому тайфун ослабевает.", "accepted": null, "short": "Двигатель тайфуна — тёплая вода: она испаряется, влажный воздух поднимается и отдаёт тепло. Над сушей «топлива» нет, и тайфун слабеет.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «над сушей горы мешают». Горы тоже тормозят, но главное — над сушей нет тёплой воды, питающей циклон.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о том, что тайфун получает энергию (тепло и влагу) от тёплой поверхности океана за счёт испарения, а над сушей этот источник исчезает.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-kilimanjaro", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nСнега Килиманджаро\nКилиманджаро — высочайшая вершина Африки (5895 м). Гора находится в Танзании, всего в 300 км к югу от экватора. У её подножия раскинулась саванна, где пасутся жирафы и антилопы. Выше по склонам растут влажные горные леса, затем их сменяют заросли кустарников и луга, ещё выше — каменистая пустыня. А на вершине лежат снега и ледники. За последние сто лет площадь ледников Килиманджаро уменьшилась более чем на 80 %, и учёные считают, что они могут совсем исчезнуть.\n\nКак называется закономерная смена природных комплексов в горах от подножия к вершинам?", "answer": "высотная поясность", "accepted": ["высотная поясность", "высотная зональность", "вертикальная поясность", "высотные пояса", "вертикальная зональность", "высотные природные пояса"], "short": "Смена природных поясов в горах с высотой называется высотной поясностью.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «широтная зональность»: она — про смену зон от экватора к полюсам, а не с высотой.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-kilimanjaro", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nСнега Килиманджаро\nКилиманджаро — высочайшая вершина Африки (5895 м). Гора находится в Танзании, всего в 300 км к югу от экватора. У её подножия раскинулась саванна, где пасутся жирафы и антилопы. Выше по склонам растут влажные горные леса, затем их сменяют заросли кустарников и луга, ещё выше — каменистая пустыня. А на вершине лежат снега и ледники. За последние сто лет площадь ледников Килиманджаро уменьшилась более чем на 80 %, и учёные считают, что они могут совсем исчезнуть.\n\nОбъясните, почему на вершине Килиманджаро лежат снега и ледники, хотя гора находится почти на экваторе.", "answer": "С высотой температура воздуха понижается — примерно на 6 °С на каждый километр подъёма. На высоте почти 6 км воздух на 30–35 °С холоднее, чем у подножия, поэтому там морозы и снег не тает.", "accepted": null, "short": "Чем выше, тем холоднее: каждые 1000 м — минус 6 °С. На высоте почти 6 км даже на экваторе мороз.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «там дует холодный ветер» или «близко к Солнцу — значит, жарко». Причина — понижение температуры с высотой.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о понижении температуры воздуха с высотой (примерно на 6 °С на каждый километр подъёма).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-alps-rivers", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nРеки, рождённые в Альпах\nАльпы — самые высокие горы Западной Европы. Их вершины покрыты вечными снегами, а в долинах медленно сползают сотни ледяных потоков; самый большой из них, Алечский, тянется на 23 км. В Альпах берут начало крупные реки Европы: Рейн, Рона, По, притоки Дуная. Интересно, что Рейн и Рона несут больше всего воды не весной, как реки Восточно-Европейской равнины, а в середине лета, в июле, когда в горах стоят самые тёплые дни. Альпийские реки используют для получения электроэнергии: в горах построено много гидроэлектростанций.\n\nКак называются массы льда, образовавшиеся из снега в горах или полярных районах и медленно движущиеся вниз по склону?", "answer": "ледники", "accepted": ["ледники", "ледник", "горные ледники", "горный ледник", "ледники (глетчеры)", "глетчеры"], "short": "Медленно движущиеся массы льда, образовавшиеся из снега, называются ледниками (в горах — горными).", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «айсберги» — это обломки ледников, плавающие в море. Или «снежники» — они не двигаются.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-alps-rivers", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nРеки, рождённые в Альпах\nАльпы — самые высокие горы Западной Европы. Их вершины покрыты вечными снегами, а в долинах медленно сползают сотни ледяных потоков; самый большой из них, Алечский, тянется на 23 км. В Альпах берут начало крупные реки Европы: Рейн, Рона, По, притоки Дуная. Интересно, что Рейн и Рона несут больше всего воды не весной, как реки Восточно-Европейской равнины, а в середине лета, в июле, когда в горах стоят самые тёплые дни. Альпийские реки используют для получения электроэнергии: в горах построено много гидроэлектростанций.\n\nОбъясните, почему реки Рейн и Рона наиболее полноводны в середине лета.", "answer": "Эти реки начинаются в Альпах и питаются водой тающих горных снегов и ледников. Сильнее всего снега и ледники тают в самое тёплое время — летом, поэтому в июле в реках больше всего воды.", "accepted": null, "short": "Реки питаются тающими ледниками и высокогорными снегами, а они тают сильнее всего в июле.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «летом идут дожди». Дожди играют роль, но главное — таяние ледников и снегов в горах.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о ледниковом (снего-ледниковом) питании рек: летом в горах тают ледники и снега.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-tundra", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nБолота тундры\nТундра Северной Америки и Евразии — безлесные пространства у берегов Северного Ледовитого океана. Осадков здесь выпадает мало, 200–300 мм в год, — почти как в полупустынях. И всё же летом тундра превращается в огромное болото: повсюду озёра, лужи и топи, над которыми вьются тучи комаров. Лето короткое и прохладное, средняя температура июля не выше +10 °С. Уже на глубине нескольких десятков сантиметров земля не оттаивает даже летом: промёрзшие слои земли сохраняются здесь тысячи лет.\n\nКак называются горные породы, которые долгое время (не менее двух-трёх лет) не оттаивают и находятся при отрицательной температуре?", "answer": "многолетняя мерзлота", "accepted": ["многолетняя мерзлота", "вечная мерзлота", "многолетнемёрзлые породы", "многолетнемерзлые породы", "мерзлота", "многолетняя мерзлота (вечная мерзлота)"], "short": "Породы, которые годами не оттаивают, называют многолетней (вечной) мерзлотой.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «лёд» или «ледник». Ледник лежит на поверхности, а мерзлота — это промёрзшая земля.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-tundra", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nБолота тундры\nТундра Северной Америки и Евразии — безлесные пространства у берегов Северного Ледовитого океана. Осадков здесь выпадает мало, 200–300 мм в год, — почти как в полупустынях. И всё же летом тундра превращается в огромное болото: повсюду озёра, лужи и топи, над которыми вьются тучи комаров. Лето короткое и прохладное, средняя температура июля не выше +10 °С. Уже на глубине нескольких десятков сантиметров земля не оттаивает даже летом: промёрзшие слои земли сохраняются здесь тысячи лет.\n\nОбъясните, почему в тундре много болот, хотя атмосферных осадков выпадает мало.", "answer": "Многолетняя мерзлота не пропускает воду вглубь, и она застаивается на поверхности. Кроме того, из-за низких температур испарение очень мало, поэтому даже небольшое количество осадков приводит к избытку влаги.", "accepted": null, "short": "Вода не уходит вниз — мешает мерзлота, и почти не испаряется — холодно. Поэтому даже малые осадки дают болота.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что много дождей» — в тексте сказано, что осадков мало. Причина — мерзлота и слабое испарение.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о многолетней мерзлоте, которая не даёт воде просачиваться в почву, ИЛИ о малом испарении из-за низких температур (осадков больше, чем испаряется).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-serengeti", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nВеликая миграция в Серенгети\nНациональный парк Серенгети в Танзании знаменит одним из самых грандиозных зрелищ в мире животных. Каждый год около 1,5 миллиона антилоп гну, сотни тысяч зебр и газелей совершают переход по кругу длиной около 3000 км. В сезон дождей стада пасутся на сочных травах южных равнин, а с началом сухого сезона уходят на север, к реке Мара, где дольше сохраняются трава и вода. За стадами следуют львы, гиены и гепарды, а при переправе через реки животных подстерегают крокодилы. Вокруг — бескрайние травянистые равнины с редкими зонтичными акациями.\n\nКак называется природная зона с травянистой растительностью и редкими деревьями, расположенная в субэкваториальном поясе?", "answer": "саванна", "accepted": ["саванна", "саванны", "саванны и редколесья", "саванны и редкостойные леса", "саванны и редколесья (саванны)"], "short": "Травянистые равнины с редкими деревьями в субэкваториальном поясе — это саванны и редколесья.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «степь»: степь находится в умеренном поясе, деревьев там почти нет, а акаций и антилоп гну нет совсем.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-serengeti", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nВеликая миграция в Серенгети\nНациональный парк Серенгети в Танзании знаменит одним из самых грандиозных зрелищ в мире животных. Каждый год около 1,5 миллиона антилоп гну, сотни тысяч зебр и газелей совершают переход по кругу длиной около 3000 км. В сезон дождей стада пасутся на сочных травах южных равнин, а с началом сухого сезона уходят на север, к реке Мара, где дольше сохраняются трава и вода. За стадами следуют львы, гиены и гепарды, а при переправе через реки животных подстерегают крокодилы. Вокруг — бескрайние травянистые равнины с редкими зонтичными акациями.\n\nОбъясните, почему стада антилоп гну и зебр каждый год совершают далёкие переходы.", "answer": "В субэкваториальном климате саванн влажный сезон сменяется сухим. В сухой сезон трава выгорает и пересыхают водоёмы, поэтому животные уходят туда, где ещё есть корм и вода, а с началом дождей возвращаются.", "accepted": null, "short": "В саванне чередуются сезон дождей и сухой сезон. Животные идут за травой и водой туда, где они ещё есть.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «спасаются от хищников» — хищники идут за стадами, а не наоборот. Причина — сухой сезон.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о смене влажного и сухого сезонов (в сухой сезон не хватает корма/травы и воды).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-congo-soils", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nБедные почвы богатого леса\nВлажные леса бассейна реки Конго — второй по площади массив тропических лесов на Земле после Амазонии. Здесь круглый год жарко (+25…+28 °С) и выпадает 1500–2500 мм осадков. Лес растёт в несколько ярусов, деревья достигают 50–60 м. Казалось бы, почвы под таким пышным лесом должны быть очень плодородными, но это не так: слой перегноя в красно-жёлтых почвах очень тонкий. Опавшие листья и ветки на земле не залёживаются — уже через несколько недель они исчезают. Когда лес вырубают под поля, урожаи хорошие лишь первые два-три года.\n\nКак называется климатический пояс, в котором круглый год жарко и выпадает много осадков, а сезоны года не выражены?", "answer": "экваториальный", "accepted": ["экваториальный", "экваториальный пояс", "экваториальный климатический пояс", "экваториальный климат"], "short": "Круглый год жарко и влажно, сезонов нет — так бывает в экваториальном климатическом поясе.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «тропический»: в тропическом поясе осадков мало (пустыни), а в субэкваториальном есть сухой сезон.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-congo-soils", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nБедные почвы богатого леса\nВлажные леса бассейна реки Конго — второй по площади массив тропических лесов на Земле после Амазонии. Здесь круглый год жарко (+25…+28 °С) и выпадает 1500–2500 мм осадков. Лес растёт в несколько ярусов, деревья достигают 50–60 м. Казалось бы, почвы под таким пышным лесом должны быть очень плодородными, но это не так: слой перегноя в красно-жёлтых почвах очень тонкий. Опавшие листья и ветки на земле не залёживаются — уже через несколько недель они исчезают. Когда лес вырубают под поля, урожаи хорошие лишь первые два-три года.\n\nОбъясните, почему почвы влажных экваториальных лесов бедны перегноем, хотя растительности здесь очень много.", "answer": "При высокой температуре и большой влажности опавшие листья и ветки очень быстро разлагаются микроорганизмами, а питательные вещества сразу поглощают корни деревьев или вымывают обильные дожди. Поэтому перегной в почве почти не накапливается.", "accepted": null, "short": "В жаре и сырости опад разлагается за недели, вещества тут же забирают корни или смывают ливни — перегною не из чего копиться.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «мало листьев падает» — листьев много, но они слишком быстро разлагаются.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о быстром разложении органических остатков в жарком влажном климате ИЛИ о вымывании веществ из почвы обильными осадками (перегной не успевает накапливаться).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-mediterranean", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nСухое лето Рима\nРим расположен на Апеннинском полуострове, недалеко от побережья Средиземного моря, на 42° с. ш. Лето здесь жаркое и солнечное: в июле средняя температура около +25 °С, а дождей почти не бывает, трава на холмах выгорает. Зато зима мягкая и дождливая: в январе около +8 °С, бóльшая часть годовых осадков выпадает с октября по март. Растут вечнозелёные растения с жёсткими кожистыми листьями — каменный дуб, лавр, маслины, кипарисы. Такой же климат характерен для всего побережья Средиземного моря.\n\nКак называется климатический пояс, для которого характерно жаркое сухое лето и тёплая дождливая зима (климат средиземноморского типа)?", "answer": "субтропический", "accepted": ["субтропический", "субтропический пояс", "субтропический климатический пояс", "субтропики", "средиземноморский", "средиземноморский климат", "субтропический средиземноморский"], "short": "Средиземноморский климат с сухим летом и дождливой зимой — это климат субтропического пояса.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «тропический»: в тропиках дождей мало круглый год, а зимних дождей и прохладной зимы нет.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-mediterranean", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nСухое лето Рима\nРим расположен на Апеннинском полуострове, недалеко от побережья Средиземного моря, на 42° с. ш. Лето здесь жаркое и солнечное: в июле средняя температура около +25 °С, а дождей почти не бывает, трава на холмах выгорает. Зато зима мягкая и дождливая: в январе около +8 °С, бóльшая часть годовых осадков выпадает с октября по март. Растут вечнозелёные растения с жёсткими кожистыми листьями — каменный дуб, лавр, маслины, кипарисы. Такой же климат характерен для всего побережья Средиземного моря.\n\nОбъясните, почему в Риме дожди выпадают в основном зимой, а лето сухое.", "answer": "Рим находится в субтропическом поясе, где воздушные массы меняются по сезонам. Летом сюда приходит сухой тропический воздух (высокое давление), и дождей нет. Зимой приходит влажный умеренный воздух с западными ветрами и циклонами, которые приносят дожди.", "accepted": null, "short": "Субтропики живут «на два воздуха»: летом — сухой тропический, зимой — влажный умеренный с циклонами. Отсюда сухое лето и дождливая зима.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «зимой холоднее, поэтому идёт дождь». Причина — смена воздушных масс и ветров по сезонам.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о смене воздушных масс по сезонам: летом господствуют тропические (сухие) воздушные массы, зимой — умеренные (влажные) с западными ветрами.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-peru-fish", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nРыбное богатство Перу\nУ берегов Перу и Чили находится один из самых богатых рыбой районов Мирового океана. Здесь ловят огромное количество перуанского анчоуса — небольшой стайной рыбы; из неё делают рыбную муку для корма скоту. На прибрежных островах гнездятся миллионы морских птиц, а их помёт — гуано — с давних времён используют как удобрение. Вода у этих берегов заметно холоднее, чем в других районах океана на тех же широтах. Вдоль побережья на север течёт течение, а ветры отгоняют поверхностную воду от берега, и на её место поднимается вода с глубины, богатая питательными веществами. Раз в несколько лет течение ослабевает, тёплая вода подходит к берегу, и рыба уходит.\n\nКак называется холодное течение, проходящее вдоль западного побережья Южной Америки?", "answer": "Перуанское", "accepted": ["Перуанское", "Перуанское течение", "течение Гумбольдта", "Гумбольдтово течение", "Перуанское (Гумбольдта)"], "short": "Вдоль западного побережья Южной Америки на север течёт холодное Перуанское течение (течение Гумбольдта).", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «Бразильское» (оно тёплое и проходит у восточного побережья) или «Западных Ветров» (оно проходит южнее, вокруг Антарктиды).", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-peru-fish", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nРыбное богатство Перу\nУ берегов Перу и Чили находится один из самых богатых рыбой районов Мирового океана. Здесь ловят огромное количество перуанского анчоуса — небольшой стайной рыбы; из неё делают рыбную муку для корма скоту. На прибрежных островах гнездятся миллионы морских птиц, а их помёт — гуано — с давних времён используют как удобрение. Вода у этих берегов заметно холоднее, чем в других районах океана на тех же широтах. Вдоль побережья на север течёт течение, а ветры отгоняют поверхностную воду от берега, и на её место поднимается вода с глубины, богатая питательными веществами. Раз в несколько лет течение ослабевает, тёплая вода подходит к берегу, и рыба уходит.\n\nОбъясните, почему у берегов Перу так много рыбы.", "answer": "У берегов Перу проходит холодное течение, и сюда поднимаются глубинные воды, богатые питательными веществами. В такой воде бурно развивается планктон, которым питаются рыбы, поэтому рыбы здесь очень много.", "accepted": null, "short": "Холодная глубинная вода приносит к поверхности питательные вещества — бурно растёт планктон, а за ним приходит рыба.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «в тёплой воде больше рыбы» — наоборот, здесь рыбу «кормит» холодное течение и подъём глубинных вод.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о холодном течении и/или подъёме к поверхности глубинных вод, богатых питательными веществами (много планктона — корма для рыбы).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-great-lakes", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nВеликие озёра\nВеликие озёра Северной Америки — Верхнее, Мичиган, Гурон, Эри и Онтарио — самая большая система пресных озёр на Земле: в них около 20 % всей пресной озёрной воды планеты. Озёра соединены протоками; между озёрами Эри и Онтарио река Ниагара низвергается с уступа высотой более 50 м. Около 20 тыс. лет назад вся эта территория была покрыта мощным покровным ледником толщиной до 2–3 км. На берегах озёр сохранились отполированные скалы и огромные валуны, принесённые издалека. По озёрам и реке Святого Лаврентия морские суда могут проходить из Атлантического океана в глубь материка.\n\nКак называется природный уступ в русле реки, с которого вода падает с высоты?", "answer": "водопад", "accepted": ["водопад", "водопады"], "short": "Место, где река падает с уступа в русле, называется водопадом; пример в тексте — Ниагарский водопад.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «пороги»: на порогах река бурлит на мелководье с камнями, но не падает отвесно.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-great-lakes", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nВеликие озёра\nВеликие озёра Северной Америки — Верхнее, Мичиган, Гурон, Эри и Онтарио — самая большая система пресных озёр на Земле: в них около 20 % всей пресной озёрной воды планеты. Озёра соединены протоками; между озёрами Эри и Онтарио река Ниагара низвергается с уступа высотой более 50 м. Около 20 тыс. лет назад вся эта территория была покрыта мощным покровным ледником толщиной до 2–3 км. На берегах озёр сохранились отполированные скалы и огромные валуны, принесённые издалека. По озёрам и реке Святого Лаврентия морские суда могут проходить из Атлантического океана в глубь материка.\n\nОбъясните, как образовались котловины Великих озёр.", "answer": "Котловины Великих озёр выпахал древний покровный ледник: двигаясь, он углубил понижения рельефа. Когда ледник растаял, котловины заполнились талой водой.", "accepted": null, "short": "Ледник толщиной в километры углубил низины, а талая вода их заполнила — так появились Великие озёра.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «озёра образовались в разломах» или «их вырыли реки». В тексте подсказка — следы ледника на берегах.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о ледниковом происхождении котловин (котловины выпаханы / углублены древним покровным ледником и заполнены талыми водами).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-fjords", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nЗаливы Норвегии\nПобережье Норвегии сильно изрезано узкими извилистыми заливами, которые на десятки и даже сотни километров врезаются в сушу. Самый длинный из них тянется на 204 км, а его глубина достигает 1300 м — гораздо глубже, чем море у входа в залив. Берега фьордов отвесные, высотой в сотни метров, со скал срываются водопады. Долины имеют корытообразную форму, а на дне находят отложения, которые оставляют ледники. В горах Скандинавии и сейчас есть ледники, а в прошлом весь полуостров покрывал мощный ледяной щит.\n\nКак называются узкие, длинные и глубокие морские заливы с высокими крутыми берегами?", "answer": "фьорды", "accepted": ["фьорды", "фьорд", "фиорды", "фиорд"], "short": "Узкие длинные глубокие заливы с отвесными берегами называются фьордами.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «лиманы» или «лагуны»: это мелкие заливы с низкими берегами.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-fjords", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nЗаливы Норвегии\nПобережье Норвегии сильно изрезано узкими извилистыми заливами, которые на десятки и даже сотни километров врезаются в сушу. Самый длинный из них тянется на 204 км, а его глубина достигает 1300 м — гораздо глубже, чем море у входа в залив. Берега фьордов отвесные, высотой в сотни метров, со скал срываются водопады. Долины имеют корытообразную форму, а на дне находят отложения, которые оставляют ледники. В горах Скандинавии и сейчас есть ледники, а в прошлом весь полуостров покрывал мощный ледяной щит.\n\nОбъясните, как образовались фьорды на побережье Норвегии.", "answer": "Древние ледники, спускавшиеся с гор Скандинавии к морю, углубили и расширили речные долины и разломы, сделав их корытообразными и глубокими. После таяния ледников эти долины затопило море.", "accepted": null, "short": "Ледники выпахали глубокие корытообразные долины, а потом в них зашло море.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «их размыло волнами». Волны так глубоко не размывают — работу сделал ледник.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о деятельности древних ледников, углубивших долины, которые затем были затоплены морем.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-arabia", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nВода Аравийского полуострова\nАравийский полуостров — самый большой полуостров на Земле. Почти всю его территорию занимают пустыни; в самой большой из них, Руб-эль-Хали, песчаные барханы поднимаются на 250 м. Летом температура воздуха превышает +50 °С, а осадков в год выпадает меньше 100 мм. На полуострове нет ни одной постоянной реки, есть лишь сухие русла — вади, по которым вода течёт только после редких ливней. Страны полуострова богаты нефтью, а пресную воду получают, удаляя соли из морской воды, — здесь работают крупнейшие в мире установки для этого.\n\nКак называют процесс получения пресной воды из морской с помощью удаления из неё солей?", "answer": "опреснение", "accepted": ["опреснение", "опреснение воды", "опреснение морской воды", "обессоливание", "дистилляция"], "short": "Удаление солей из морской воды для получения пресной называется опреснением.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «фильтрация» или «очистка»: обычный фильтр соль не убирает, термин — опреснение.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-arabia", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nВода Аравийского полуострова\nАравийский полуостров — самый большой полуостров на Земле. Почти всю его территорию занимают пустыни; в самой большой из них, Руб-эль-Хали, песчаные барханы поднимаются на 250 м. Летом температура воздуха превышает +50 °С, а осадков в год выпадает меньше 100 мм. На полуострове нет ни одной постоянной реки, есть лишь сухие русла — вади, по которым вода течёт только после редких ливней. Страны полуострова богаты нефтью, а пресную воду получают, удаляя соли из морской воды, — здесь работают крупнейшие в мире установки для этого.\n\nОбъясните, почему на Аравийском полуострове нет постоянных рек.", "answer": "Полуостров лежит в тропическом поясе, где круглый год господствует высокое давление и сухой тропический воздух. Осадков выпадает очень мало, а испарение из-за жары огромное, поэтому постоянным рекам неоткуда получать воду.", "accepted": null, "short": "Тропический пустынный климат: дождей почти нет, а жара сразу испаряет то, что выпало. Рекам нечем питаться.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что там пустыня» — это следствие, а не причина. Нужно назвать сухой климат: мало осадков, сильное испарение.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о сухом тропическом климате: очень мало осадков (высокое давление, тропические воздушные массы) и/или сильное испарение.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-labrador", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nЛабрадор и Британия\nПолуостров Лабрадор в Северной Америке и Британские острова в Европе лежат почти на одних и тех же широтах — между 50° и 60° с. ш. Но природа там совсем разная. На Лабрадоре зима долгая и морозная, средняя температура января около –20 °С, у берегов даже летом плавают льды, на севере полуострова раскинулась тундра. На Британских островах в январе +3…+7 °С, снег лежит недолго, круглый год зеленеют луга, и коров пасут на них почти всю зиму. Вдоль берегов Лабрадора на юг течёт течение, которое выносит из Арктики огромные ледяные глыбы, а к берегам Британии с юго-запада приходят течение из тропических широт и влажные ветры с океана.\n\nКак называются крупные глыбы льда, отколовшиеся от ледников и плавающие в океане?", "answer": "айсберги", "accepted": ["айсберги", "айсберг"], "short": "Глыбы льда, отколовшиеся от ледников и плавающие в море, — айсберги.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «льдины» или «торосы»: льдины — куски морского льда, а айсберги откалываются от ледников.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-labrador", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nЛабрадор и Британия\nПолуостров Лабрадор в Северной Америке и Британские острова в Европе лежат почти на одних и тех же широтах — между 50° и 60° с. ш. Но природа там совсем разная. На Лабрадоре зима долгая и морозная, средняя температура января около –20 °С, у берегов даже летом плавают льды, на севере полуострова раскинулась тундра. На Британских островах в январе +3…+7 °С, снег лежит недолго, круглый год зеленеют луга, и коров пасут на них почти всю зиму. Вдоль берегов Лабрадора на юг течёт течение, которое выносит из Арктики огромные ледяные глыбы, а к берегам Британии с юго-запада приходят течение из тропических широт и влажные ветры с океана.\n\nОбъясните, почему зима на Британских островах намного теплее, чем на полуострове Лабрадор, расположенном на тех же широтах.", "answer": "К берегам Британских островов подходит тёплое Северо-Атлантическое течение, а западные ветры приносят оттуда тёплый влажный морской воздух. Вдоль Лабрадора проходит холодное Лабрадорское течение, а западные ветры дуют туда с холодного материка.", "accepted": null, "short": "Широты одинаковые, но течения разные: к Британии приходит тёплое течение и морской воздух с запада, а Лабрадор омывает холодное течение.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «Британия ближе к экватору» — в тексте сказано, что широты одинаковые. Причина — течения и западные ветры.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о тёплом (Северо-Атлантическом) течении у берегов Британских островов ИЛИ о холодном (Лабрадорском) течении у Лабрадора ИЛИ о западных ветрах, приносящих к Британии тёплый морской воздух.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-egypt-pop", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nНаселение Египта\nЕгипет — одна из самых многонаселённых стран Африки: в ней живут более 110 миллионов человек. Средняя плотность населения в стране около 110 человек на 1 км², но население размещено крайне неравномерно. Почти все жители сосредоточены в узкой долине и дельте Нила, которые занимают лишь около 5 % территории страны; там плотность населения превышает 1500 человек на 1 км² — одна из самых высоких в мире. Остальные 95 % территории почти безлюдны: это пустыни, где лишь там, где из-под земли выходят источники, есть небольшие поселения с пальмовыми рощами.\n\nКак называются участки в пустыне, где есть вода и растительность и возможна жизнь людей?", "answer": "оазисы", "accepted": ["оазисы", "оазис"], "short": "Участки пустыни с водой (источники, подземные воды, реки) и растительностью называются оазисами.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «долины» или «поселения». Термин для таких участков пустыни — оазис.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-egypt-pop", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nНаселение Египта\nЕгипет — одна из самых многонаселённых стран Африки: в ней живут более 110 миллионов человек. Средняя плотность населения в стране около 110 человек на 1 км², но население размещено крайне неравномерно. Почти все жители сосредоточены в узкой долине и дельте Нила, которые занимают лишь около 5 % территории страны; там плотность населения превышает 1500 человек на 1 км² — одна из самых высоких в мире. Остальные 95 % территории почти безлюдны: это пустыни, где лишь там, где из-под земли выходят источники, есть небольшие поселения с пальмовыми рощами.\n\nОбъясните, почему почти всё население Египта живёт в долине и дельте Нила.", "answer": "Египет почти целиком лежит в тропической пустыне, где очень мало осадков. Только в долине и дельте Нила есть вода для питья и орошения полей и плодородные почвы, поэтому там можно заниматься земледелием и жить.", "accepted": null, "short": "Вокруг пустыня. Вода и плодородный ил есть только у Нила — поэтому люди живут вдоль реки.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «там столица» или «там красиво». Главное — вода и плодородные земли посреди пустыни.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о том, что только в долине и дельте Нила есть пресная вода (для орошения) и/или плодородные почвы, а остальная территория — пустыня.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-pampa", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nПампа\nПампа — обширные равнины в Аргентине и Уругвае. Раньше они были покрыты высокими травами — ковылём, мятликом, бородачом, деревьев почти не было. Климат субтропический, умеренно влажный: на востоке выпадает около 1000 мм осадков, к западу — меньше. Под травами за тысячи лет сформировались тёмные почвы с толстым слоем перегноя, похожие на чернозёмы. Сегодня бóльшая часть пампы распахана: здесь выращивают пшеницу, кукурузу и сою, а на пастбищах пасутся многомиллионные стада крупного рогатого скота. Аргентина — один из крупнейших в мире экспортёров зерна и говядины.\n\nКак называется отрасль сельского хозяйства, связанная с выращиванием культурных растений — пшеницы, кукурузы, сои?", "answer": "растениеводство", "accepted": ["растениеводство", "земледелие", "растениеводство (земледелие)", "полеводство"], "short": "Выращивание культурных растений — это растениеводство (земледелие); разведение скота — животноводство.", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «животноводство» — это разведение скота, а вопрос про выращивание растений.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-pampa", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nПампа\nПампа — обширные равнины в Аргентине и Уругвае. Раньше они были покрыты высокими травами — ковылём, мятликом, бородачом, деревьев почти не было. Климат субтропический, умеренно влажный: на востоке выпадает около 1000 мм осадков, к западу — меньше. Под травами за тысячи лет сформировались тёмные почвы с толстым слоем перегноя, похожие на чернозёмы. Сегодня бóльшая часть пампы распахана: здесь выращивают пшеницу, кукурузу и сою, а на пастбищах пасутся многомиллионные стада крупного рогатого скота. Аргентина — один из крупнейших в мире экспортёров зерна и говядины.\n\nОбъясните, почему почвы пампы очень плодородны.", "answer": "Под густой травянистой растительностью ежегодно отмирает много корней и надземных частей трав. При умеренном увлажнении они не вымываются и не успевают полностью разложиться, поэтому в почве накапливается толстый слой перегноя.", "accepted": null, "short": "Травы каждый год отмирают и дают много органики, а умеренное увлажнение не вымывает её — копится перегной.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «потому что их удобряют». Плодородие природное — от перегноя из отмерших трав.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о накоплении перегноя от ежегодно отмирающей травянистой растительности (при умеренном увлажнении).\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t16-patagonia", "task": 16, "type": "input_text_short", "template": "vpr7-16-text-term", "text": "Прочитайте текст и ответьте на вопрос.\n\nПатагония\nПатагония — южная часть Южной Америки, к югу от 40° ю. ш. Её западная часть — это склоны Анд, обращённые к Тихому океану. Там почти круглый год идут дожди, на некоторых участках выпадает более 5000 мм осадков в год, растут густые влажные леса, а с гор спускаются крупные ледники. А на восточной стороне Анд раскинулись сухие ступенчатые возвышенные равнины, ограниченные уступами: осадков там всего 150–250 мм в год, растут колючие кустарники и жёсткие злаки, дуют сильные холодные ветры. На этих скудных пастбищах разводят овец. В этих широтах круглый год господствуют ветры, дующие с запада.\n\nКак называются равнины, лежащие на значительной высоте над уровнем моря и ограниченные уступами (как на востоке Патагонии)?", "answer": "плато", "accepted": ["плато", "плоскогорье", "плоскогорья", "плато (плоскогорье)", "столовая равнина"], "short": "Возвышенные равнины, ограниченные крутыми уступами, — плато (плоскогорья).", "alg": "1. Прочитай текст и вопрос: что именно просят назвать — термин, явление, тип объекта.\n2. Найди в тексте место, о котором спрашивают, и вспомни, как это называется в учебнике.\n3. Запиши термин одним-двумя словами.", "mistakes": "Пишут «низменность»: низменности лежат ниже 200 м над уровнем моря, а плато — высоко.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}, {"key": "t17-patagonia", "task": 17, "type": "input_text_long", "template": "vpr7-17-text-explain", "text": "Прочитайте текст и ответьте на вопрос.\n\nПатагония\nПатагония — южная часть Южной Америки, к югу от 40° ю. ш. Её западная часть — это склоны Анд, обращённые к Тихому океану. Там почти круглый год идут дожди, на некоторых участках выпадает более 5000 мм осадков в год, растут густые влажные леса, а с гор спускаются крупные ледники. А на восточной стороне Анд раскинулись сухие ступенчатые возвышенные равнины, ограниченные уступами: осадков там всего 150–250 мм в год, растут колючие кустарники и жёсткие злаки, дуют сильные холодные ветры. На этих скудных пастбищах разводят овец. В этих широтах круглый год господствуют ветры, дующие с запада.\n\nОбъясните, почему на западе Патагонии выпадает очень много осадков, а на востоке — очень мало.", "answer": "Влажные западные ветры приходят с Тихого океана и поднимаются по западным склонам Анд; воздух охлаждается, и почти вся влага выпадает на наветренных склонах. На восточную, подветренную сторону гор воздух приходит уже сухим.", "accepted": null, "short": "Западные ветры несут влагу с океана, Анды её «отжимают» на западных склонах, а за горами остаётся сухой воздух.", "alg": "1. Найди в вопросе, что нужно объяснить (почему…).\n2. Вспомни, какие факторы влияют на это явление: широта, океан и течения, ветры, рельеф, строение земной коры.\n3. Назови причину и коротко свяжи её со следствием: «потому что…, поэтому…». Пересказ текста — это не объяснение.", "mistakes": "Пишут «восток дальше от океана». Атлантика рядом с восточной Патагонией — дело в горах и западных ветрах.", "difficulty": 3, "kind": "text_long", "rubric": "Содержание верного ответа и указания по оцениванию (допускаются иные формулировки ответа, не искажающие его смысла)\nВ ответе говорится о том, что Анды задерживают влажные западные ветры с Тихого океана: осадки выпадают на западных (наветренных) склонах, а на восток (подветренная сторона) воздух приходит сухим.\n1 балл — ответ содержит названный выше элемент.\n0 баллов — все ответы, которые не соответствуют вышеуказанному критерию.", "max_score": 1, "image": null, "topic": "2.6.3", "topics2": [], "batch": "b2"}]$json$::jsonb) as x(
